/* Floating bottom-tab navigation — the fleet's canonical primary-nav component.
 *
 * VENDORED VERBATIM from project-scaffolding. Do NOT edit this file per-app:
 * the only things that vary per app are the *markup* (which tabs exist) and the
 * options passed at the call site. Pair it with nav-tabs.css (the visual
 * contract — the floating bottom-tab pill) and nav-tabs.html (the markup
 * skeleton). This file owns *behaviour* only; all colour/spacing comes from the
 * design-system tokens in ~/.claude/design.md, consumed by nav-tabs.css.
 *
 * Normalized from home-automation's app/webapp/static/tabs.js, which hardcoded
 * a fixed tab list and imported its app's state module. Here the switcher
 * discovers tabs + panes from the DOM, so adding or removing a tab is a
 * markup-only change and the file stays byte-identical across every app.
 *
 * Markup contract (see nav-tabs.html):
 *   <nav class="tabs" role="tablist" data-active-tab="…">
 *     <button class="tab" data-tab="NAME" role="tab"
 *             aria-controls="PANE_ID" aria-selected="…"> … </button> …
 *   </nav>
 *   <main class="app">
 *     <section id="PANE_ID" class="pane" role="tabpanel" aria-labelledby="…"> … </section>
 *   </main>
 *
 * Each .tab carries data-tab (its name) and aria-controls (the id of the pane it
 * shows). The nav element must be a direct <body> child, sibling to the .app
 * content wrapper; iOS installed PWAs can capture fixed descendants of scrollers
 * and anchor them to short-tab content. The chosen tab is remembered in
 * localStorage so an installed PWA reopens where you left it. The modal-hide rule
 * (hide the bar while a <dialog> is open) lives entirely in nav-tabs.css — no JS
 * needed.
 */

'use strict';

/**
 * Wire up a .tabs nav: discover its tabs from the DOM, restore the last-active
 * tab from localStorage, switch panes on click, and keep ARIA + roving tabindex
 * in sync.
 *
 * @param {object} [opts]
 * @param {string} [opts.navSelector='.tabs']   selector for the <nav> element.
 * @param {string|null} [opts.storageKey=null]  localStorage key for the active
 *   tab; omit / pass null to disable persistence.
 * @param {(tab: string) => void} [opts.onChange]  called after every switch
 *   (including the initial restore), with the active tab name.
 * @param {string|null} [opts.defaultTab=null]  tab to select when nothing is
 *   stored; defaults to the first tab in DOM order.
 * @returns {{
 *   setTab: (tab: string) => void,
 *   getTab: () => string,
 *   setBadge: (tab: string, count: number|null|undefined, noun?: string, tone?: string) => void,
 * }} setBadge shows a count badge on the tab named by data-tab: 1–9 render the
 *   digit, 10 and up render "9+", and 0 / null / undefined / a non-number remove
 *   it. The optional `noun` is what the count counts ("waiting"), spoken as part
 *   of the tab's accessible name: setBadge('board', 2, 'waiting') → "Board, 2
 *   waiting". The optional `tone` is 'attention' (the default) or 'danger', set
 *   as `data-tone` on the badge; any other value renders as attention. An unknown
 *   tab is ignored, so a poll loop can call it freely.
 */
export function initNavTabs(opts = {}) {
  const {
    navSelector = '.tabs',
    storageKey = null,
    onChange = function () {},
    defaultTab = null,
  } = opts;

  const nav = document.querySelector(navSelector);
  if (!nav) throw new Error('initNavTabs: no element matches "' + navSelector + '"');

  const buttons = Array.from(nav.querySelectorAll('.tab[data-tab]'));
  if (!buttons.length) throw new Error('initNavTabs: nav has no .tab[data-tab] buttons');

  const tabs = discoverTabs(buttons);
  const pill = mountPill(nav);

  const names = Array.from(tabs.keys());
  const fallback = defaultTab && tabs.has(defaultTab) ? defaultTab : names[0];
  let current = fallback;

  function setTab(tab) {
    if (!tabs.has(tab)) tab = fallback;
    current = tab;
    tabs.forEach(function (entry, name) {
      const active = name === tab;
      entry.button.classList.toggle('active', active);
      entry.button.setAttribute('aria-selected', active ? 'true' : 'false');
      entry.button.tabIndex = active ? 0 : -1;
      if (entry.pane) entry.pane.hidden = !active;
    });
    nav.dataset.activeTab = tab;
    placePill(nav, pill, false);
    // Each pane opens at its top; the document is the only scroller.
    window.scrollTo(0, 0);
    if (storageKey) {
      try { localStorage.setItem(storageKey, tab); } catch (_) { /* private mode */ }
    }
    onChange(tab);
  }

  function initialTab() {
    if (storageKey) {
      try {
        const stored = localStorage.getItem(storageKey);
        if (stored && tabs.has(stored)) return stored;
      } catch (_) { /* private mode */ }
    }
    return fallback;
  }

  function setBadge(tab, count, noun, tone) {
    const entry = tabs.get(tab);
    if (entry) paintBadge(entry.button, count, noun, tone);
  }

  buttons.forEach(function (button) {
    button.addEventListener('click', function () { setTab(button.dataset.tab); });
  });

  setTab(initialTab());
  expandStandaloneViewport();
  // Rotation, a desktop↔phone width crossing or a text-size change moves the
  // tab cells: re-place the capsule without a slide.
  window.addEventListener('resize', function () { placePill(nav, pill, true); }, { passive: true });

  return { setTab: setTab, getTab: function () { return current; }, setBadge: setBadge };
}

// An installed iOS app opens with its viewport 59px short of the screen and,
// on a cold launch, grows it 1px at a time over ~3s, painting nothing below
// the moving edge, so the bar is revealed slowly. A 1px programmatic scroll
// asks iOS for the full-height viewport at once; the page goes straight back
// to the top. Once, at startup, and only when the page has not been scrolled.
function expandStandaloneViewport() {
  if (!window.matchMedia('(display-mode: standalone)').matches) return;
  if (window.scrollY !== 0) return;
  window.scrollTo(0, 1);
  requestAnimationFrame(function () {
    if (window.scrollY === 1) window.scrollTo(0, 0);
  });
}

// tab name → { button, pane }. The pane is resolved from aria-controls; a tab
// may legitimately have no pane (e.g. an external link), in which case pane is
// null and only the button state is toggled.
function discoverTabs(buttons) {
  const tabs = new Map();
  buttons.forEach(function (button) {
    const name = button.dataset.tab;
    const pane = document.getElementById(button.getAttribute('aria-controls') || '');
    tabs.set(name, { button: button, pane: pane });
  });
  return tabs;
}

// Optional count badge. Nothing here touches the DOM
// until an app calls setBadge, so an app that never does renders as before.
// The badge sits on the icon's top-right corner: the first badge wraps the
// icon in .tab-icon-wrap (the positioning box) and the last one unwraps it.
function paintBadge(button, count, noun, tone) {
  const n = Math.floor(Number(count));
  const icon = button.querySelector('.tab-icon');
  let badge = button.querySelector('.tab-badge');
  let hidden = button.querySelector('.tab-badge-sr');

  if (!(n > 0)) {
    if (badge) badge.remove();
    if (hidden) hidden.remove();
    const wrap = icon && icon.parentElement;
    if (wrap && wrap.classList.contains('tab-icon-wrap')) wrap.replaceWith(icon);
    return;
  }

  if (!badge) {
    badge = document.createElement('span');
    badge.className = 'tab-badge';
    // The visible digit is decoration; the count is spoken once, by the
    // visually hidden text below, as part of the tab's accessible name.
    badge.setAttribute('aria-hidden', 'true');
    if (icon) {
      let wrap = icon.parentElement;
      if (!wrap.classList.contains('tab-icon-wrap')) {
        wrap = document.createElement('span');
        wrap.className = 'tab-icon-wrap';
        icon.replaceWith(wrap);
        wrap.appendChild(icon);
      }
      wrap.appendChild(badge);
    } else {
      button.appendChild(badge);
    }
  }
  badge.textContent = n > 9 ? '9+' : String(n);
  // Set on every call, so a count that escalates to danger (and settles back)
  // repaints the existing badge without removing it first.
  badge.dataset.tone = tone === 'danger' ? 'danger' : 'attention';

  if (!hidden) {
    hidden = document.createElement('span');
    hidden.className = 'tab-badge-sr';
    // Inside the label, so the name reads "Board, 2 waiting" with no stray gap.
    (button.querySelector('.tab-label') || button).appendChild(hidden);
  }
  hidden.textContent = ', ' + n + (noun ? ' ' + noun : '');
}

// The sliding active capsule. Inserted by the script, not the markup, so every
// app's nav HTML stays as it is; CSS shows it only in the mobile pill. It starts
// with .no-anim so its first placement jumps instead of sliding in.
function mountPill(nav) {
  const pill = document.createElement('span');
  pill.className = 'tab-pill no-anim';
  pill.setAttribute('aria-hidden', 'true');
  nav.prepend(pill);
  return pill;
}

// Move the capsule onto the active tab. `jump` places it without the spring
// (resize, rotation); otherwise the CSS transition carries it there. Two frames
// after a jump the transition is re-armed, so the next tap springs. .has-pill
// hands the active tab's own capsule paint over to this element.
function placePill(nav, pill, jump) {
  const on = nav.querySelector('.tab.active');
  if (!on || !on.offsetWidth) return;
  if (jump) pill.classList.add('no-anim');
  pill.style.setProperty('--pill-x', on.offsetLeft + 'px');
  pill.style.setProperty('--pill-w', on.offsetWidth + 'px');
  nav.classList.add('has-pill');
  if (pill.classList.contains('no-anim')) {
    requestAnimationFrame(function () {
      requestAnimationFrame(function () { pill.classList.remove('no-anim'); });
    });
  }
}
